/**
 * CS 7314 Markov-OP: well-formedness checks on the projected usage profile and its
 * walk generator. These validate the MODEL; the usage-based test runs themselves are
 * generated by scripts/testing/markov-walk.ts and executed in the second half.
 */
import { describe, expect, it } from "vitest";
import { P, SCREENS, expectedVisits, rng, walk } from "./models/usageProfile";

describe("Markov usage profile (projected-v1)", () => {
  it("MK-01 every row is a probability distribution", () => {
    for (const s of SCREENS) {
      const row = Object.values(P[s]);
      expect(row.every((p) => p! >= 0 && p! <= 1)).toBe(true);
      expect(row.reduce((a, b) => a! + b!, 0)).toBeCloseTo(1, 10);
    }
  });

  it("MK-02 EXIT is reachable from every screen (the chain is absorbing)", () => {
    for (const s of SCREENS) {
      const seen = new Set([s]);
      const queue = [s];
      while (queue.length) {
        const cur = queue.shift()!;
        for (const [to, p] of Object.entries(P[cur])) {
          if (p! > 0 && !seen.has(to as never)) {
            seen.add(to as never);
            queue.push(to as never);
          }
        }
      }
      expect(seen.has("EXIT")).toBe(true);
    }
  });

  it("MK-03 every screen is reachable from START", () => {
    const visited = new Set<string>();
    const next = rng(7);
    for (let i = 0; i < 2000; i++) walk(next).forEach((s) => visited.add(s));
    expect([...visited].sort()).toEqual([...SCREENS].sort());
  });

  it("MK-04 the walk generator is reproducible for a fixed seed", () => {
    const a = Array.from({ length: 5 }, ((n) => () => walk(n))(rng(42)));
    const b = Array.from({ length: 5 }, ((n) => () => walk(n))(rng(42)));
    expect(a).toEqual(b);
  });

  it("MK-05 simulated visit frequencies agree with the analytic fundamental matrix", () => {
    const analytic = expectedVisits();
    const next = rng(2026);
    const counts: Record<string, number> = {};
    const N = 20_000;
    for (let i = 0; i < N; i++) for (const s of walk(next, 500)) counts[s] = (counts[s] ?? 0) + 1;
    for (const s of ["FEED", "PERCHES", "LISTING", "BOOKING"] as const) {
      expect(counts[s] / N).toBeCloseTo(analytic[s], 1);
    }
  });
});
